<?php
declare(strict_types=1);
require_once __DIR__.'/CompanyPortal.php';
require_once __DIR__.'/SalesNumberPresentation.php';

/** Read historical native estimates only for a verified, financially authorized principal contact. */
final class NativePortalLegacyEstimates
{
 public function __construct(private $db,private string $p,private CompanyPortal $portal){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid prefix');$portal->assertStorageBinding($db,$p);}
 private function rows(string$sql,array$args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
 private function tables():array{$tables=['issuers_lock','issuers_registry','issuers_installation_identity','issuers_clients','clients','contacts','contact_permissions','options','estimates','currencies','itemable','item_tax','issuers_audit'];if($this->db->table_exists($this->p.'files'))$tables[]='files';return$tables;}
 private function identity(array$binding,int$issuer):array{
  $who=$this->portal->invoiceIdentity($binding,$issuer,true);if(!$who||(new IssuerResourceAccess($this->db,$this->p))->primaryId()!==$issuer||$this->rows('SELECT client_id FROM '.$this->p.'issuers_clients WHERE client_id=?',[$who['client_id']]))throw new DomainException('company_portal_sales_unavailable');
  $contact=$this->rows('SELECT email_verified_at FROM '.$this->p.'contacts WHERE id=? AND userid=?',[$who['contact_id'],$who['client_id']]);$grants=$this->rows('SELECT permission_id FROM '.$this->p.'contact_permissions WHERE userid=? AND permission_id=2',[$who['contact_id']]);if(count($contact)!==1||$contact[0]['email_verified_at']===null||count($grants)!==1)throw new DomainException('company_portal_sales_unavailable');return$who;
 }
 private function suffix():string{return IssuerStorage::fieldExists($this->db,'issuer_id',$this->p.'estimates')?' AND e.issuer_id IS NULL':'';}
 private function options(int$issuer):array{$settings=new CompanySettingsStorage($this->db,$this->p);$exclude=$settings->exists($issuer,'exclude_estimate_from_client_area_with_draft_status')?$settings->get($issuer,'exclude_estimate_from_client_area_with_draft_status'):'1';$padding=$settings->exists($issuer,'number_padding_prefixes')?$settings->get($issuer,'number_padding_prefixes'):'0';if(!in_array($exclude,['0','1'],true)||!preg_match('/^(?:[0-9]|1[0-9]|20)$/D',(string)$padding))throw new DomainException('company_portal_sales_unavailable');return[$exclude,(int)$padding];}
 public function page(array$binding,int$issuer):array{return$this->pageCursor($binding,$issuer,0)['items'];}
 public function pageCursor(array$binding,int$issuer,int$before=0,int$status=0):array{if($before<0||$status<0||$status>5)throw new DomainException('company_portal_sales_unavailable');return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$before,$status){$who=$this->identity($binding,$issuer);[$exclude,$padding]=$this->options($issuer);$filter=' FROM '.$this->p.'estimates e JOIN '.$this->p.'currencies c ON c.id=e.currency WHERE e.clientid=?'.$this->suffix().' AND e.status IN (2,3,4,5'.($exclude==='0'?',1':'').')'.($status?' AND e.status=?':'');$args=[$who['client_id']];if($status)$args[]=$status;$total=(int)($this->rows('SELECT COUNT(*) n'.$filter,$args)[0]['n']??0);$pagedArgs=$args;if($before)$pagedArgs[]=$before;$rows=$this->rows('SELECT e.id,e.number,e.prefix,e.number_format,e.date,e.expirydate,e.status,e.total,e.hash,c.name currency'.$filter.($before?' AND e.id<?':'').' ORDER BY e.id DESC LIMIT 101',$pagedArgs);$hasMore=count($rows)>100;$rows=array_slice($rows,0,100);foreach($rows as&$row){if(!is_string($row['hash'])||!preg_match('/^[A-Za-z0-9]{32}$/D',$row['hash']))throw new DomainException('company_portal_sales_unavailable');$row['formatted_number']=(int)$row['status']===1?$row['prefix'].'DRAFT':SalesNumberPresentation::format($row['number'],$row['number_format'],$row['prefix'],$row['date'],$padding);unset($row['number'],$row['prefix'],$row['number_format']);}unset($row);if($this->identity($binding,$issuer)!==$who||$this->options($issuer)!==[$exclude,$padding])throw new DomainException('company_portal_sales_unavailable');return['items'=>$rows,'next'=>$hasMore?(int)$rows[count($rows)-1]['id']:null,'total'=>$total];});}
 public function document(array$binding,int$issuer,int$id,string$hash):array{if($id<1||!preg_match('/^[A-Za-z0-9]{32}$/D',$hash))throw new DomainException('company_portal_sales_unavailable');return IssuerTransaction::run($this->db,$this->p,$this->tables(),fn()=>$this->documentInOwned($binding,$issuer,$id,$hash));}
 private function documentInOwned(array$binding,int$issuer,int$id,string$hash):array{IssuerTransaction::assertOwned($this->db,$this->p,$this->tables());$who=$this->identity($binding,$issuer);[$exclude,$padding]=$this->options($issuer);$rows=$this->rows('SELECT e.id,e.number,e.prefix,e.number_format,e.date,e.expirydate,e.status,e.total,e.subtotal,e.total_tax,e.discount_total,e.adjustment,e.clientnote,e.terms,e.hash,c.name currency,r.legal_name issuer_name,r.tax_id issuer_tax_id,o.company client_name,o.vat client_tax_id FROM '.$this->p.'estimates e JOIN '.$this->p.'currencies c ON c.id=e.currency JOIN '.$this->p.'clients o ON o.userid=e.clientid JOIN '.$this->p.'issuers_registry r ON r.id=? WHERE e.id=? AND e.clientid=?'.$this->suffix().' FOR UPDATE',[$issuer,$id,$who['client_id']]);if(count($rows)!==1||!is_string($rows[0]['hash'])||!hash_equals($rows[0]['hash'],$hash)||!in_array((int)$rows[0]['status'],[1,2,3,4,5],true)||((int)$rows[0]['status']===1&&$exclude==='1'))throw new DomainException('company_portal_sales_unavailable');$row=$rows[0];$row['formatted_number']=(int)$row['status']===1?$row['prefix'].'DRAFT':SalesNumberPresentation::format($row['number'],$row['number_format'],$row['prefix'],$row['date'],$padding);unset($row['number'],$row['prefix'],$row['number_format'],$row['hash']);$row['items']=$this->rows("SELECT id,description,long_description,qty,rate,unit,is_optional,is_selected FROM {$this->p}itemable WHERE rel_id=? AND rel_type='estimate' ORDER BY item_order,id LIMIT 1001",[$id]);if(count($row['items'])>1000)throw new DomainException('company_portal_sales_unavailable');foreach($row['items'] as &$item){if(!in_array((string)$item['is_optional'],['0','1'],true)||!in_array((string)$item['is_selected'],['0','1'],true))throw new DomainException('company_portal_sales_unavailable');$item['taxes']=$this->rows("SELECT taxname name,taxrate rate FROM {$this->p}item_tax WHERE itemid=? AND rel_id=? AND rel_type='estimate' ORDER BY id",[$item['id'],$id]);unset($item['id']);}unset($item);if($this->identity($binding,$issuer)!==$who||$this->options($issuer)!==[$exclude,$padding])throw new DomainException('company_portal_sales_unavailable');return$row;}
 public function confirm(array$binding,int$issuer,int$id,string$hash,array$before,string$contentHash):void{if(!preg_match('/^[a-f0-9]{64}$/D',$contentHash))throw new DomainException('company_portal_sales_unavailable');IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash,$before,$contentHash){if($this->documentInOwned($binding,$issuer,$id,$hash)!==$before)throw new DomainException('company_portal_sales_unavailable');$metadata=json_encode(['contact_id'=>$binding['contact_id'],'client_id'=>$binding['client_id'],'sha256'=>$contentHash,'receipt'=>bin2hex(random_bytes(16))],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(0,?,?,?,?,?)',['native_portal_legacy_estimate_pdf_downloaded',$issuer,$id,date('Y-m-d H:i:s'),$metadata]);$audit=(int)$this->db->insert_id();if(count($this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND subject_id=? AND metadata_json=?',[$audit,$issuer,$id,$metadata]))!==1)throw new RuntimeException('issuer_portal_write_unconfirmed');});}
 public function attachments(array$binding,int$issuer,int$id,string$hash):array{return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash){$before=$this->documentInOwned($binding,$issuer,$id,$hash);if(!$this->db->table_exists($this->p.'files'))return[];$rows=$this->rows("SELECT file_name,attachment_key,external,external_link FROM {$this->p}files WHERE rel_type='estimate' AND rel_id=? AND visible_to_customer=1 ORDER BY id LIMIT 101",[$id]);if(count($rows)>100)throw new DomainException('company_portal_sales_unavailable');$result=[];require_once __DIR__.'/NativeCompanyFileContent.php';foreach($rows as$row){if(!is_string($row['file_name'])||$row['file_name']===''||strlen($row['file_name'])>191||preg_match('/[\x00-\x1f\x7f]/',$row['file_name']))throw new DomainException('company_portal_sales_unavailable');$external=(string)($row['external']??'');if($external!=='')$result[]=['filename'=>$row['file_name'],'external'=>NativeCompanyFileContent::external($external,(string)$row['external_link']),'file_key'=>null];else{if(!is_string($row['attachment_key'])||!preg_match('/^[a-f0-9]{32}$/D',$row['attachment_key']))throw new DomainException('company_portal_sales_unavailable');$result[]=['filename'=>$row['file_name'],'external'=>null,'file_key'=>$row['attachment_key']];}}if($this->documentInOwned($binding,$issuer,$id,$hash)!==$before)throw new DomainException('company_portal_sales_unavailable');return$result;});}
 public function file(array$binding,int$issuer,int$id,string$hash,string$key):array{if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('company_portal_sales_unavailable');return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash,$key){$before=$this->documentInOwned($binding,$issuer,$id,$hash);if(!$this->db->table_exists($this->p.'files'))throw new DomainException('company_portal_sales_unavailable');$rows=$this->rows("SELECT id,file_name,external FROM {$this->p}files WHERE rel_type='estimate' AND rel_id=? AND attachment_key=? AND visible_to_customer=1 FOR UPDATE",[$id,$key]);if(count($rows)!==1||!empty($rows[0]['external']))throw new DomainException('company_portal_sales_unavailable');require_once __DIR__.'/NativeCompanyLegacyInvoiceContent.php';$content=NativeCompanyLegacyInvoiceContent::readEstimate($id,(string)$rows[0]['file_name']);$content['filename']=$rows[0]['file_name'];if($this->documentInOwned($binding,$issuer,$id,$hash)!==$before)throw new DomainException('company_portal_sales_unavailable');$metadata=json_encode(['contact_id'=>$binding['contact_id'],'client_id'=>$binding['client_id'],'file_id'=>(int)$rows[0]['id'],'sha256'=>$content['content_hash'],'receipt'=>bin2hex(random_bytes(16))],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(0,?,?,?,?,?)',['native_portal_legacy_estimate_file_downloaded',$issuer,$id,date('Y-m-d H:i:s'),$metadata]);$audit=(int)$this->db->insert_id();if(count($this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND subject_id=? AND metadata_json=?',[$audit,$issuer,$id,$metadata]))!==1)throw new RuntimeException('issuer_portal_write_unconfirmed');return$content;});}
}
